    dist_matrix = get(instance, "distance_matrix", None)
    if dist_matrix is None:
        dist_matrix = get(instance, "dist", None)

    if customers is None:
        if n is not None:
            customers = [i for i in range(n) if i != depot]
        elif isinstance(demands, dict):
            customers = [k for k in demands.keys() if k != depot]
        elif coords is not None:
            customers = [i for i in range(len(coords)) if i != depot]
        elif dist_matrix is not None:
            customers = [i for i in range(len(dist_matrix)) if i != depot]
        else:
            customers = []
    customers = [c for c in to_list(customers) if c != depot]

    capacity = get(instance, "capacity", None)
    if capacity is None:
        capacity = get(instance, "vehicle_capacity", None)
    if capacity is None:
        capacity = 10 ** 18

    if isinstance(demands, dict):
        def demand(c):
            return demands.get(c, 0)
    elif isinstance(demands, (list, tuple)):
        def demand(c):
            return demands[c] if 0 <= c < len(demands) else 0
    else:
        def demand(c):
            return 0

    def dist(i, j):
        if dist_matrix is not None:
            return dist_matrix[i][j]
        if coords is not None:
            a = coords[i]
            b = coords[j]
            dx = a[0] - b[0]
            dy = a[1] - b[1]
            return (dx * dx + dy * dy) ** 0.5
        return abs(i - j)

    def route_load(r):
        s = 0
        for x in r:
            s += demand(x)
        return s

    def route_cost(r):
        if not r:
            return 0
        s = dist(depot, r[0])
        for i in range(len(r) - 1):
            s += dist(r[i], r[i + 1])
        s += dist(r[-1], depot)
        return s

    def insert_delta(r, c, pos):
        a = depot if pos == 0 else r[pos - 1]
        b = depot if pos == len(r) else r[pos]
        return dist(a, c) + dist(c, b) - dist(a, b)

    def best_insertion_pos(r, c):
        best_pos = 0
        best_delta = None
        for pos in range(len(r) + 1):
            dlt = insert_delta(r, c, pos)
            if best_delta is None or dlt < best_delta - 1e-12 or (abs(dlt - best_delta) <= 1e-12 and pos < best_pos):
                best_delta = dlt
                best_pos = pos
        return best_pos, best_delta

    unserved = set(customers)
    routes = []
    if not unserved:
        return []

    seeds = sorted(unserved, key=lambda c: (-demand(c), -dist(depot, c), c))
    while unserved:
        seed = None
        while seeds and seed is None:
            cand = seeds.pop(0)
            if cand in unserved:
                seed = cand
        if seed is None:
            seed = min(unserved)
        r = [seed]
        unserved.remove(seed)
        load = demand(seed)

        while True:
            best = None
            best_pos = None
            best_delta = None
            for c in sorted(unserved, key=lambda x: (dist(r[-1], x), -demand(x), x)):
                dc = demand(c)
                if load + dc > capacity:
                    continue
                pos, dlt = best_insertion_pos(r, c)
                if best_delta is None or dlt < best_delta - 1e-12 or (abs(dlt - best_delta) <= 1e-12 and (c < best or (c == best and pos < best_pos))):
                    best = c
                    best_pos = pos
                    best_delta = dlt
            if best is None:
                break
            r.insert(best_pos, best)
            load += demand(best)
            unserved.remove(best)
        routes.append(r)

    # Repair: insert any stragglers into cheapest feasible routes
    if unserved:
        for c in sorted(unserved, key=lambda x: (-demand(x), dist(depot, x), x)):
            best_i = None
            best_pos = None
            best_delta = None
            for i, r in enumerate(routes):
                if route_load(r) + demand(c) > capacity:
                    continue
                pos, dlt = best_insertion_pos(r, c)
                if best_delta is None or dlt < best_delta - 1e-12:
                    best_i, best_pos, best_delta = i, pos, dlt
            if best_i is None:
                routes.append([c])
            else:
                routes[best_i].insert(best_pos, c)

    def two_opt_route(r):
        best = r[:]
        best_cost = route_cost(best)
        improved = True
        while improved:
            improved = False
            n0 = len(best)
            for i in range(n0 - 2):
                for j in range(i + 2, n0):
                    cand = best[:i] + best[i:j + 1][::-1] + best[j + 1:]
                    cc = route_cost(cand)
                    if cc < best_cost - 1e-12 or (abs(cc - best_cost) <= 1e-12 and cand < best):
                        best, best_cost = cand, cc
                        improved = True
                        break
                if improved:
                    break
        return best

    def relocate_move(routes):
        best_gain = 0
        best = None
        base_costs = [route_cost(r) for r in routes]
        loads = [route_load(r) for r in routes]
        for i, r1 in enumerate(routes):
            for a_idx, a in enumerate(r1):
                pre1 = depot if a_idx == 0 else r1[a_idx - 1]
                post1 = depot if a_idx == len(r1) - 1 else r1[a_idx + 1]
                remove_gain = dist(pre1, a) + dist(a, post1) - dist(pre1, post1)
                for j, r2 in enumerate(routes):
                    if i == j:
                        continue
                    if loads[j] + demand(a) > capacity:
                        continue
                    for pos in range(len(r2) + 1):
                        ins = insert_delta(r2, a, pos)
                        gain = remove_gain - ins
                        if gain > best_gain + 1e-12:
                            best_gain = gain
                            best = (i, a_idx, j, pos, a)
        if best is None:
            return False
        i, a_idx, j, pos, a = best
        if i < j:
            routes[i].pop(a_idx)
            routes[j].insert(pos, a)
        elif i > j:
            routes[j].insert(pos, a)
            routes[i].pop(a_idx)
        else:
            return False
        return True

    def swap_move(routes):
        best_gain = 0
        best = None
        loads = [route_load(r) for r in routes]
        for i in range(len(routes)):
            for j in range(i + 1, len(routes)):
                r1 = routes[i]
                r2 = routes[j]
                for a_idx, a in enumerate(r1):
                    for b_idx, b in enumerate(r2):
                        new_load1 = loads[i] - demand(a) + demand(b)
                        new_load2 = loads[j] - demand(b) + demand(a)
                        if new_load1 > capacity or new_load2 > capacity:
                            continue
                        pre_a = depot if a_idx == 0 else r1[a_idx - 1]
                        post_a = depot if a_idx == len(r1) - 1 else r1[a_idx + 1]
                        pre_b = depot if b_idx == 0 else r2[b_idx - 1]
                        post_b = depot if b_idx == len(r2) - 1 else r2[b_idx + 1]
                        old = dist(pre_a, a) + dist(a, post_a) + dist(pre_b, b) + dist(b, post_b)
                        new = dist(pre_a, b) + dist(b, post_a) + dist(pre_b, a) + dist(a, post_b)
                        gain = old - new
                        if gain > best_gain + 1e-12:
                            best_gain = gain
                            best = (i, a_idx, j, b_idx)
        if best is None:
            return False
        i, a_idx, j, b_idx = best
        routes[i][a_idx], routes[j][b_idx] = routes[j][b_idx], routes[i][a_idx]
        return True

    # Local search
    for _ in range(3):
        changed = True
        while changed:
            changed = False
            for idx in range(len(routes)):
                nr = two_opt_route(routes[idx])
                if nr != routes[idx]:
                    routes[idx] = nr
                    changed = True
            if relocate_move(routes):
                changed = True
                continue
            if swap_move(routes):
                changed = True

    routes = [r for r in routes if r]
    return routes
